content = note['content']

# Extract movie blocks: title lines occur before ' - director:' lines.
# We'll parse line by line: title is a line not starting with '#', not empty, and not starting with '-' and contains no ':'? but titles can have ':'.
lines = [ln.rstrip() for ln in content.splitlines()]

# Simple state machine: when we see a title candidate, store current_title.
# When we encounter a line like ' - director: X', we assign director to current_title.
movies=[]
current_title=None
for ln in lines:
    ln_stripped = ln.strip()
    if not ln_stripped or ln_stripped.startswith('#'):
        continue
    if ln_stripped.startswith('-'):
        # director line
        m = re.match(r"-\s*director\s*:\s*(.*)$", ln_stripped)
        if m and current_title:
            director = m.group(1).strip()
            movies.append((current_title, director))
            current_title=None
        continue
    # Otherwise title line
    current_title = ln_stripped

# Deduplicate titles by first appearance
seen=set()
filtered=[]
for title,director in movies:
    if director == 'Peter Jackson':
        if title not in seen:
            seen.add(title)
            filtered.append(title)

print('matches', filtered, 'count', len(filtered))
